<?php
namespace App\Modules\Sales\Presentation\Http\Controllers;
use App\Http\Controllers\Controller;use App\Modules\Identity\Domain\Models\AuthorizationRequest;use App\Modules\Sales\Domain\Models\Sale;use Illuminate\Http\Request;use Inertia\Inertia;use Inertia\Response;
class ShowSaleController extends Controller {public function __invoke(Request $request,Sale $sale):Response{abort_unless($request->user()->hasPermission('sales.create')||$request->user()->hasPermission('finance.view'),403);$sale->load(['customer:id,name','order:id,document_number','lines.presentation.item:id,name','lines.priceOverride','receivable','returns']);$auth=AuthorizationRequest::query()->where('resource_type',$sale->getMorphClass())->where('resource_id',$sale->id)->get();return Inertia::render('sales/Show',['sale'=>[...$sale->only(['id','document_number','subtotal','discount','total','advance_applied','paid_amount','balance_amount','cost_of_goods_sold','gross_profit','payment_plan']),'customer'=>$sale->customer?->name??'Consumidor final','order'=>$sale->order?->document_number,'sold_at'=>$sale->sold_at->format('Y-m-d H:i'),'due_at'=>$sale->due_at?->format('Y-m-d'),'status'=>$sale->status->value,'status_label'=>$sale->status->label(),'returned_amount'=>$sale->returns->where('status','confirmed')->sum('total_refund'),'lines'=>$sale->lines->map(fn($l)=>[...$l->only(['id','quantity','list_unit_price','applied_unit_price','discount','line_total','unit_cost','total_cost','price_reason']),'product'=>"{$l->presentation->item->name} — {$l->presentation->name}",'minimum_price'=>$l->priceOverride?->minimum_price]),'returns'=>$sale->returns->sortByDesc('returned_at')->values()->map(fn($r)=>['id'=>$r->id,'document_number'=>$r->document_number,'returned_at'=>$r->returned_at->format('Y-m-d H:i'),'total_refund'=>$r->total_refund,'reason'=>$r->reason])],'authorizations'=>$auth->map(fn($a)=>['id'=>$a->id,'permission'=>$a->approval_permission,'status'=>$a->status->value,'usable'=>$a->isUsable(),'reason'=>$a->reason]),'canConfirm'=>$request->user()->hasPermission('sales.create'),'canReturn'=>$request->user()->hasPermission('sales.return'),'canRequestAuthorization'=>$request->user()->hasPermission('authorizations.request'),'canViewMargin'=>$request->user()->hasPermission('finance.view')]);}}
